int sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct ctl_dir *dir_header;
    int ret;

    dir_header = (struct ctl_dir *)file->f_path.dentry->d_inode->i_private;
    if (!dir_header)
        return -EFAULT;

    ret = dir_emit(ctx, ".", 1, (unsigned long)NULL, DT_DIR);
    if (ret < 0)
        return ret;

    ret = dir_emit(ctx, "..", 2, (unsigned long)NULL, DT_DIR);
    if (ret < 0)
        return ret;

    ret = 0;
    while (dir_header && !ret) {
        ret = dir_header->scan(dir_header, ctx);
        if (ret < 0)
            break;
        dir_header = dir_header->next;
    }

    dir_header->header.finished = 1;
    return 0;
}

