int sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct sysctl_dir_header *header;
    int ret;

    header = sysctl_get_dir_header(file);
    if (!header)
        return -EFAULT;

    ret = dir_emit_dot(file, ctx);
    if (ret)
        return ret;

    ret = dir_emit_dotdot(file, ctx);
    if (ret)
        return ret;

    while (header != NULL) {
        ret = sysctl_scan_entry(file, ctx, header);
        if (ret < 0) {
            sysctl_finish_header(header);
            return ret;
        }

        header = sysctl_next_header(header);
    }

    sysctl_finish_header(header);
    return 0;
}

int sysctl_file_readdir(struct file *file, struct dir_context *ctx) {
    struct ctl_dir *dir_header;
    int ret = 0;

    dir_header = get_ctl_dir_header(file);
    if (!dir_header)
        return -ENOENT;

    dir_emit_dot(ctx);
    dir_emit_dotdot(ctx);

    while (!dir_context_pos(ctx, 0)) {
        struct ctl_entry *entry;
        entry = get_next_ctl_entry(dir_header);

        if (!entry)
            break;

        ret = scan_ctl_entry(entry, ctx);
        if (ret < 0) {
            finish_ctl_dir(dir_header);
            return ret;
        }
    }

    finish_ctl_dir(dir_header);
    return 0;
}

